package com.silverguardian.prototype.ai;
import static org.junit.Assert.*;import org.junit.runner.RunWith;import org.robolectric.RobolectricTestRunner;import com.silverguardian.prototype.models.MedicineLibraryItem;import java.util.*;import org.junit.Test;
@RunWith(RobolectricTestRunner.class) public class DrugRecommendationParserTest{@Test public void parsesAndHidesJson(){DrugRecommendationParser.Result r=DrugRecommendationParser.parse("建议咨询医生 {\"drugs\":[{\"name\":\"缬沙坦\",\"type\":\"降压药\",\"usage\":\"遵医嘱\"}]}",Collections.emptyList());assertEquals(1,r.drugs.size());assertFalse(r.visibleText.contains("\"drugs\""));}@Test public void fallsBackOnlyToLibraryNames(){List<MedicineLibraryItem>lib=Collections.singletonList(new MedicineLibraryItem(1,"高血压","缬沙坦","代文","降压药",""));assertEquals(1,DrugRecommendationParser.parse("可以咨询医生是否适合缬沙坦",lib).drugs.size());assertTrue(DrugRecommendationParser.parse("注意休息",lib).drugs.isEmpty());}}